const memo = (p) => { for (let j = p.used.length - 1; j >= 0; j--) { const id = p.used[j]; if (!FXOK(id)) return j; } return -1; };
const FXOK = (id) => id === 245 || id === 245 + PLUS || [190, 191, 192, 193, 194, 195, 283, 283 + PLUS].includes(id);
